  "board.c4_final.words.w_xzs": "principal’s office",
  "board.c4_final.words.w_tsg": "library",
  "board.c4_final.words.w_hl": "Han Li",
  "board.c4_final.words.w_xj": "Xu Jia",
  "board.c4_final.words.w_gqb": "Gu Qiubai",
  "board.c4_final.words.w_grade": "the Senior Three grades database",
  "board.c4_final.words.w_jiaoan": "lesson plans",
